use MyDatabase; CREATE TABLE Departments (    DeptID INT PRIMARY KEY,    DeptName VARCHAR(50),    Location VARCHAR(50));INSERT INTO Departments VALUES(1, 'IT', 'Delhi'),(2, 'HR', 'Mumbai'),(3, 'Finance', 'Delhi');SELECT * FROm Departments;SELECT * FROm Employees;-- basic Sub Query based on above tables -- Show employees who are earning more than average salary SELECT FirstName, Salary FROM dbo.EmployeesWHERE Salary > (SELECT AVG(Salary) FROM dbo.Employees);-- Subquery with In operator-- Employees who are from Delhi SELECT FIRSTName, Department FROM dbo.EmployeesWHERE Department IN (SELECT DeptName FROM dbo.Departments WHERE Location = 'Delhi');SELECT FirstName, Salary, Department FROM dbo.Employees EWHERE Salary > (    SELECT AVG(Salary)     FROM dbo.Employees     WHERE Department = E.Department);---Step by step trigger creation and implementation in MSSQL Server based on above tables--1) Create a trigger that automatically updates the Location column in the Departments table when a new employee is added to the Employees table with a specific department.CREATE TRIGGER trg_UpdateDepartmentLocationON dbo.EmployeesAFTER INSERT -- here we are using after insert trigger because we want to update the location in department table after new employee is added in employee table ASBEGIN    -- Update the Location in Departments table based on the Department of the newly inserted employee    UPDATE D    SET D.Location = 'Updated Location' -- You can set this to a specific location based on your requirements    FROM dbo.Departments D    JOIN inserted I ON D.DeptName = I.DepartmentEND;--2) Insert a new employee to test the triggerINSERT INTO dbo.Employees (EmpID, FirstName, LastName, Department, Salary) VALUES (10, 'John', 'Snow', 'IT', 50000);